1	package darksafe
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"strings"
8		"unicode/utf16"
9		"unicode/utf8"
10	)
11	
12	// This file holds the single structural reading of a release configuration
13	// document, shared by the two checks that run before business validation:
14	// the strict text check (stricttext.go) and the duplicate-member check
15	// (plan.go). Both checks need exactly the same structural rules — how
16	// objects, arrays and literals nest, how a string literal is read and
17	// decoded, and how the JSONPath-style location of each position is built —
18	// so those rules live here once, in jsonWalker. Each check is then only its
19	// own policy layered on the walk: the text check rejects corrupt strings,
20	// the duplicate check rejects repeated member names within one object.
21	//
22	// The walker reads the raw document bytes, before any decoding layer can
23	// rewrite corrupt text to the replacement character "�" (U+FFFD), and
24	// decodes every string itself. Member names are reported to the checks in
25	// the same decoded form that business validation later compares, so a name
26	// written literally and the same name written with \uXXXX escapes are one
27	// name everywhere.
28	//
29	// The walker only recognizes structure. Anything structurally unexpected
30	// makes it stop (errUndecided) and defer to the encoding/json walk in
31	// plan.go, which reports the JSON format error with the established
32	// wording — so malformed documents keep their existing error messages.
33	// Numbers are scanned loosely (their characters are skipped, not judged):
34	// whether a number is well-formed is the decoder's call, and the duplicate
35	// check confirms the document with json.Valid before trusting a completed
36	// walk.
37	
38	// errUndecided is the internal sentinel meaning "this document is not
39	// structurally recognizable here": the check stops and the encoding/json
40	// walk reports the format error instead. It is never returned to callers.
41	var errUndecided = errors.New("darksafe: unrecognized JSON structure")
42	
43	// jsonWalker is a recursive-descent reader over the raw document bytes. It
44	// sees the text before any decoding, so corrupt bytes and escapes are still
45	// visible, and it tracks the JSONPath-style location of every position as it
46	// descends. The path strings follow the convention documented on
47	// duplicateMemberError: dot notation for identifier-style member names,
48	// brackets around a JSON string for every other name, and the real
49	// zero-based index for array items.
50	type jsonWalker struct {
51		data []byte
52		pos  int
53		// onMember, when set, is called for every object member in document
54		// order with the owning object's location and the decoded member name.
55		// A non-nil result aborts the walk and is propagated to the caller.
56		onMember func(ownerPath, name string) error
57	}
58	
59	func (w *jsonWalker) skipSpace() {
60		for w.pos < len(w.data) {
61			switch w.data[w.pos] {
62			case ' ', '\t', '\n', '\r':
63				w.pos++
64			default:
65				return
66			}
67		}
68	}
69	
70	// value reads one complete JSON value at the current position.
71	func (w *jsonWalker) value(path string) error {
72		w.skipSpace()
73		if w.pos >= len(w.data) {
74			return errUndecided
75		}
76		switch c := w.data[w.pos]; {
77		case c == '{':
78			return w.object(path)
79		case c == '[':
80			return w.array(path)
81		case c == '"':
82			_, err := w.jsonString(path, false)
83			return err
84		case c == 't':
85			return w.literal("true")
86		case c == 'f':
87			return w.literal("false")
88		case c == 'n':
89			return w.literal("null")
90		case c == '-' || ('0' <= c && c <= '9'):
91			// Numbers carry no text; skip their characters loosely and let the
92			// decoder judge whether the number itself is well-formed.
93			w.number()
94			return nil
95		default:
96			return errUndecided
97		}
98	}
99	
100	func (w *jsonWalker) object(path string) error {
101		w.pos++ // consume '{'
102		w.skipSpace()
103		if w.pos < len(w.data) && w.data[w.pos] == '}' {
104			w.pos++
105			return nil
106		}
107		for {
108			w.skipSpace()
109			if w.pos >= len(w.data) || w.data[w.pos] != '"' {
110				return errUndecided
111			}
112			key, err := w.jsonString(path, true)
113			if err != nil {
114				return err
115			}
116			if w.onMember != nil {
117				if err := w.onMember(path, key); err != nil {
118					return err
119				}
120			}
121			w.skipSpace()
122			if w.pos >= len(w.data) || w.data[w.pos] != ':' {
123				return errUndecided
124			}
125			w.pos++
126			if err := w.value(joinMemberPath(path, key)); err != nil {
127				return err
128			}
129			w.skipSpace()
130			if w.pos >= len(w.data) {
131				return errUndecided
132			}
133			switch w.data[w.pos] {
134			case ',':
135				w.pos++
136			case '}':
137				w.pos++
138				return nil
139			default:
140				return errUndecided
141			}
142		}
143	}
144	
145	func (w *jsonWalker) array(path string) error {
146		w.pos++ // consume '['
147		w.skipSpace()
148		if w.pos < len(w.data) && w.data[w.pos] == ']' {
149			w.pos++
150			return nil
151		}
152		for i := 0; ; i++ {
153			if err := w.value(joinIndexPath(path, i)); err != nil {
154				return err
155			}
156			w.skipSpace()
157			if w.pos >= len(w.data) {
158				return errUndecided
159			}
160			switch w.data[w.pos] {
161			case ',':
162				w.pos++
163			case ']':
164				w.pos++
165				return nil
166			default:
167				return errUndecided
168			}
169		}
170	}
171	
172	func (w *jsonWalker) literal(word string) error {
173		if len(w.data)-w.pos < len(word) || string(w.data[w.pos:w.pos+len(word)]) != word {
174			return errUndecided
175		}
176		w.pos += len(word)
177		return nil
178	}
179	
180	func (w *jsonWalker) number() {
181		for w.pos < len(w.data) {
182			switch c := w.data[w.pos]; {
183			case c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || ('0' <= c && c <= '9'):
184				w.pos++
185			default:
186				return
187			}
188		}
189	}
190	
191	// jsonString reads one string literal whose opening quote is at w.pos,
192	// validating every byte and escape, and returns the decoded contents. The
193	// decoded form is needed for member names so that object paths are built —
194	// and duplicates compared — from the same decoded names the business
195	// validation sees.
196	func (w *jsonWalker) jsonString(path string, isKey bool) (string, error) {
197		w.pos++ // consume the opening quote
198		rawStart := w.pos
199		var sb strings.Builder
200		decoded := false // whether sb holds the decoded prefix
201		flush := func(upto int) {
202			if !decoded {
203				sb.Write(w.data[rawStart:upto])
204				decoded = true
205			}
206		}
207		for {
208			if w.pos >= len(w.data) {
209				return "", errUndecided // unterminated: the decoder reports it
210			}
211			c := w.data[w.pos]
212			switch {
213			case c == '"':
214				w.pos++
215				if !decoded {
216					return string(w.data[rawStart : w.pos-1]), nil
217				}
218				return sb.String(), nil
219			case c == '\\':
220				flush(w.pos)
221				w.pos++
222				if err := w.escape(&sb, path, isKey); err != nil {
223					return "", err
224				}
225			case c < 0x20:
226				// A raw control character is a JSON format error; leave the
227				// report to the decoder.
228				return "", errUndecided
229			case c < utf8.RuneSelf:
230				if decoded {
231					sb.WriteByte(c)
232				}
233				w.pos++
234			default:
235				r, size := utf8.DecodeRune(w.data[w.pos:])
236				// RuneError with size 1 means the bytes are not valid UTF-8; a
237				// literally written "�" decodes with size 3 and is legal text.
238				if r == utf8.RuneError && size == 1 {
239					return "", &invalidUTF8Error{path: path, isKey: isKey}
240				}
241				if decoded {
242					sb.Write(w.data[w.pos : w.pos+size])
243				}
244				w.pos += size
245			}
246		}
247	}
248	
249	// escape consumes one escape sequence (the backslash is already consumed)
250	// and writes the decoded character to sb.
251	func (w *jsonWalker) escape(sb *strings.Builder, path string, isKey bool) error {
252		if w.pos >= len(w.data) {
253			return errUndecided
254		}
255		e := w.data[w.pos]
256		w.pos++
257		switch e {
258		case '"', '\\', '/':
259			sb.WriteByte(e)
260		case 'b':
261			sb.WriteByte('\b')
262		case 'f':
263			sb.WriteByte('\f')
264		case 'n':
265			sb.WriteByte('\n')
266		case 'r':
267			sb.WriteByte('\r')
268		case 't':
269			sb.WriteByte('\t')
270		case 'u':
271			r, err := w.unicodeEscape(path, isKey)
272			if err != nil {
273				return err
274			}
275			sb.WriteRune(r)
276		default:
277			// An unknown escape is a JSON format error, reported by the decoder.
278			return errUndecided
279		}
280		return nil
281	}
282	
283	// unicodeEscape reads the four hex digits of a \uXXXX escape (the "\u" is
284	// already consumed) and, for a high surrogate, the low-surrogate escape that
285	// must immediately follow. It returns the decoded rune: the BMP character
286	// itself, or the non-BMP character a surrogate pair stands for.
287	func (w *jsonWalker) unicodeEscape(path string, isKey bool) (rune, error) {
288		r, ok := w.hex4()
289		if !ok {
290			return 0, errUndecided // malformed hex: the decoder reports it
291		}
292		if !utf16.IsSurrogate(r) {
293			return r, nil
294		}
295		unpaired := &unpairedSurrogateError{
296			escape: fmt.Sprintf(`\u%04X`, uint16(r)),
297			path:   path,
298			isKey:  isKey,
299		}
300		if r >= 0xDC00 {
301			// A low surrogate with no preceding high surrogate.
302			return 0, unpaired
303		}
304		// A high surrogate must be immediately followed by a `\uDC00`–`\uDFFF`
305		// escape; anything else — end of string, a plain character, another
306		// escape kind, or a non-low-surrogate \uXXXX — leaves it unpaired.
307		if w.pos+1 < len(w.data) && w.data[w.pos] == '\\' && w.data[w.pos+1] == 'u' {
308			w.pos += 2
309			lo, ok := w.hex4()
310			if !ok {
311				return 0, errUndecided // malformed hex: the decoder reports it
312			}
313			if lo >= 0xDC00 && lo <= 0xDFFF {
314				return utf16.DecodeRune(r, lo), nil
315			}
316		}
317		return 0, unpaired
318	}
319	
320	// hex4 reads exactly four hexadecimal digits. It reports false — consuming
321	// nothing — when they are absent or not hex, leaving the format error to the
322	// decoder.
323	func (w *jsonWalker) hex4() (rune, bool) {
324		if w.pos+4 > len(w.data) {
325			return 0, false
326		}
327		var v rune
328		for i := 0; i < 4; i++ {
329			c := w.data[w.pos+i]
330			var d byte
331			switch {
332			case '0' <= c && c <= '9':
333				d = c - '0'
334			case 'a' <= c && c <= 'f':
335				d = c - 'a' + 10
336			case 'A' <= c && c <= 'F':
337				d = c - 'A' + 10
338			default:
339				return 0, false
340			}
341			v = v*16 + rune(d)
342		}
343		w.pos += 4
344		return v, true
345	}
346	
347	// joinIndexPath extends an array location with one item's real zero-based
348	// index ("$.clusters[0]").
349	func joinIndexPath(path string, index int) string {
350		return fmt.Sprintf("%s[%d]", path, index)
351	}
352	
353	// isSimpleMemberName reports whether key may be written with dot notation:
354	// it must start with an ASCII letter or underscore and contain only ASCII
355	// letters, digits, and underscores afterward.
356	func isSimpleMemberName(key string) bool {
357		if key == "" {
358			return false
359		}
360		for i, r := range key {
361			switch {
362			case r == '_' || ('a' <= r && r <= 'z') || ('A' <= r && r <= 'Z'):
363			case i > 0 && ('0' <= r && r <= '9'):
364			default:
365				return false
366			}
367		}
368		return true
369	}
370	
371	// joinMemberPath extends an object location with one member name. Simple
372	// identifier names keep the existing dot spelling ("$.clusters[0].tags");
373	// every other name is rendered as brackets around a JSON-encoded string, so
374	// the text decodes back to exactly the real member name and none of its
375	// characters can be mistaken for a path separator or array index.
376	func joinMemberPath(path, key string) string {
377		if isSimpleMemberName(key) {
378			return path + "." + key
379		}
380		return path + "[" + jsonEncodePathString(key) + "]"
381	}
382	
383	// jsonEncodePathString renders key as a legal JSON string (including the
384	// surrounding quotes); decoding the result restores key exactly, including
385	// empty names and names containing quotes, backslashes, newlines or other
386	// control characters.
387	func jsonEncodePathString(key string) string {
388		bs, err := json.Marshal(key)
389		if err != nil {
390			// json.Marshal cannot fail for a Go string.
391			panic(fmt.Sprintf("json.Marshal(%q): %v", key, err))
392		}
393		return string(bs)
394	}
