26	// pin down how relative paths are resolved against the caller's CWD.
27	func runPlanCLIInDir(t *testing.T, dir string, args ...string) (int, string, string) {
28		t.Helper()
29		cmd := exec.Command(planBinary(t), args...)
30		cmd.Dir = dir
31		var stdout, stderr strings.Builder
